input.command:
gh api graphql -f query='
{
  repository(owner: "FSM1", name: "cipher-box") {
    pullRequest(number: 273) {
      reviewThreads(first: 100) {
        nodes {
          id
          isResolved
          comments(first: 10) {
            nodes {
              id
              databaseId
              author { login }
              body
              path
              line
              createdAt
            }
          }
        }
      }
    }
  }
}'

gh api graphql -f query='
{
  repository(owner: "FSM1", name: "cipher-box") {
    pullRequest(number: 273) {
      reviewThreads(first: 100) {
        nodes {
          id
          isResolved
          comments(first: 1) {
            nodes {
              databaseId
              author { login }
              body
              path
              line
            }
          }
        }
      }
    }
  }
}' | jq '[.data.repository.pullRequest.reviewThreads.nodes[] | select(.isResolved == false)]'

